int main(){try{auto robot=hipRollModel();const auto&m=robot.mechanics;std::vector<double>q(m.defaultQ.size());for(auto&x:q)need(bool(std::cin>>x),"missing q");std::cerr << "dof8_drive " << m.dofs[8].drive.x << " " << m.dofs[8].drive.y << " " << m.dofs[8].drive.z << std::endl; size_t n=m.defaultV.size();std::vector<double> mass(n*n),rhs(2*n),response(2*n);rhs[8]=1;rhs[n+9]=1;need(computeArticulatedMassMatrix(m,0,q,mass).succeeded(),"mass failed");need(computeArticulatedInverseMassResponses(m,0,q,rhs,response).succeeded(),"inverse failed");std::cout<<std::setprecision(16)<<"flap_fixed_other_inertia "<<mass[8*n+8]<<" "<<mass[9*n+9]<<" flap_free_effective_inertia "<<1.0/response[8]<<" "<<1.0/response[n+9]<<" free_inverse_cross "<<response[9]<<" "<<response[n+8]<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
